 "descargas/programacion/java/Cuenta.java": {
  "ruta": "descargas/programacion/java/Cuenta.java",
  "nombre": "Cuenta.java",
  "ext": "java",
  "tipo": "Código",
  "bytes": 858,
  "actualizado": "2026-11-25",
  "lenguaje": "java",
  "contenido": "/** Programación orientada a objetos: clase, atributos, métodos y encapsulamiento. */\npublic class Cuenta {\n    private final String titular;\n    private double saldo;\n\n    public Cuenta(String titular) {\n        this.titular = titular;\n        this.saldo = 0;\n    }\n\n    public void depositar(double monto) {\n        if (monto <= 0) throw new IllegalArgumentException(\"Monto inválido\");\n        saldo += monto;\n    }\n\n    public boolean extraer(double monto) {\n        if (monto > saldo) return false;\n        saldo -= monto;\n        return true;\n    }\n\n    public double getSaldo() { return saldo; }\n\n    public static void main(String[] args) {\n        Cuenta c = new Cuenta(\"Estudiante\");\n        c.depositar(1500);\n        System.out.println(\"¿Extracción de 2000? \" + c.extraer(2000));\n        System.out.println(\"Saldo: \" + c.getSaldo());\n    }\n}\n"
 },
